import json


def task_func():
    with open('inputs/reported-work-projection.json', 'r', encoding='utf-8') as source:
        data = json.load(source)

    tasks = data['action_tasks']
    providers = {}
    for task in tasks:
        provider = task['provider']
        if provider not in providers:
            providers[provider] = {
                'accepted': 0,
                'failed': 0,
                'unknown': 0,
                'reported_cost_micro_usd': 0,
                'unknown_costs': 0,
            }
        counts = providers[provider]
        acceptance = task.get('acceptance')
        passed = acceptance.get('passed') if isinstance(acceptance, dict) else None
        if passed is True:
            counts['accepted'] += 1
        elif passed is False:
            counts['failed'] += 1
        else:
            counts['unknown'] += 1

        settlement = task.get('settlement')
        amount = settlement.get('total_micro_usd') if isinstance(settlement, dict) else None
        if type(amount) is int:
            counts['reported_cost_micro_usd'] += amount
        else:
            counts['unknown_costs'] += 1

    result = {
        'reported_actions': len(tasks),
        'financial_execution': data['financial_execution'],
        'evidence': 'reported_public_projection_not_independent_payment_verification',
        'providers': providers,
    }
    with open('report.json', 'w', encoding='utf-8') as report:
        json.dump(result, report, ensure_ascii=False)
    return result

